53	   * Initialize library scan crons
54	   * @param {import('../models/Library')[]} libraries
55	   */
56	  initLibraryScanCrons(libraries) {
57	    for (const library of libraries) {
58	      if (library.settings.autoScanCronExpression) {
59	        this.startCronForLibrary(library)
60	      }
61	    }
62	  }
63	
64	  /**
65	   * Start cron schedule for library
66	   *
67	   * @param {import('../models/Library')} _library
68	   */
69	  startCronForLibrary(_library) {
70	    Logger.debug(`[CronManager] Init library scan cron for ${_library.name} on schedule ${_library.settings.autoScanCronExpression}`)
