81	      libraryId: _library.id,
82	      expression: _library.settings.autoScanCronExpression,
83	      task: libScanCron
84	    })
85	  }
86	
87	  /**
88	   *
89	   * @param {import('../models/Library')} library
90	   */
91	  removeCronForLibrary(library) {
92	    Logger.debug(`[CronManager] Removing library scan cron for ${library.name}`)
93	    this.libraryScanCrons = this.libraryScanCrons.filter((lsc) => lsc.libraryId !== library.id)
94	  }
