119	   * Init cron jobs for auto-download podcasts
120	   */
121	  async initPodcastCrons() {
122	    const cronExpressionMap = {}
123	
124	    const podcastsWithAutoDownload = await Database.podcastModel.findAll({
125	      where: {
126	        autoDownloadEpisodes: true,
127	        autoDownloadSchedule: {
128	          [Sequelize.Op.not]: null
129	        }
130	      },
131	      include: {
132	        model: Database.libraryItemModel
133	      }
134	    })
135	
136	    for (const podcast of podcastsWithAutoDownload) {
137	      if (!cronExpressionMap[podcast.autoDownloadSchedule]) {
138	        cronExpressionMap[podcast.autoDownloadSchedule] = {
139	          expression: podcast.autoDownloadSchedule,
140	          libraryItemIds: []
141	        }
142	      }
143	      cronExpressionMap[podcast.autoDownloadSchedule].libraryItemIds.push(podcast.libraryItem.id)
144	    }
145	
146	    if (!Object.keys(cronExpressionMap).length) return
147	
148	    Logger.debug(`[CronManager] Found ${Object.keys(cronExpressionMap).length} podcast episode schedules to start`)
149	    for (const expression in cronExpressionMap) {
150	      this.startPodcastCron(expression, cronExpressionMap[expression].libraryItemIds)
151	    }
152	  }
153	
154	  startPodcastCron(expression, libraryItemIds) {
155	    try {
156	      if (!cron.validate(expression)) {
157	        Logger.error(`[CronManager] Invalid auto download schedule cron expression "${expression}" - not starting podcast episode check cron`)
158	        return
159	      }
160	
161	      Logger.debug(`[CronManager] Scheduling podcast episode check cron "${expression}" for ${libraryItemIds.length} item(s)`)
162	      const task = cron.schedule(expression, () => {
163	        if (this.podcastCronExpressionsExecuting.includes(expression)) {
164	          Logger.warn(`[CronManager] Podcast cron "${expression}" is already executing`)
165	        } else {
166	          this.executePodcastCron(expression, libraryItemIds)
167	        }
168	      })
169	      this.podcastCrons.push({
170	        libraryItemIds,
171	        expression,
172	        task
173	      })
174	    } catch (error) {
175	      Logger.error(`[PodcastManager] Failed to schedule podcast cron ${expression}`, error)
176	    }
177	  }
178	
179	  async executePodcastCron(expression) {
180	    const podcastCron = this.podcastCrons.find((cron) => cron.expression === expression)
181	    if (!podcastCron) {
182	      Logger.error(`[CronManager] Podcast cron not found for expression ${expression}`)
183	      return
184	    }
185	    this.podcastCronExpressionsExecuting.push(expression)
186	
187	    const libraryItemIds = podcastCron.libraryItemIds
188	    Logger.debug(`[CronManager] Start executing podcast cron ${expression} for ${libraryItemIds.length} item(s)`)
189	
190	    // Get podcast library items to check
191	    const libraryItems = []
192	    for (const libraryItemId of libraryItemIds) {
193	      const libraryItem = await Database.libraryItemModel.getExpandedById(libraryItemId)
194	      if (!libraryItem) {
195	        Logger.error(`[CronManager] Library item ${libraryItemId} not found for episode check cron ${expression}`)
196	        podcastCron.libraryItemIds = podcastCron.libraryItemIds.filter((lid) => lid !== libraryItemId) // Filter it out
197	      } else {
198	        libraryItems.push(libraryItem)
199	      }
200	    }
201	
202	    // Run episode checks
203	    for (const libraryItem of libraryItems) {
204	      const keepAutoDownloading = await this.podcastManager.runEpisodeCheck(libraryItem)
205	      if (!keepAutoDownloading) {
206	        // auto download was disabled
207	        podcastCron.libraryItemIds = podcastCron.libraryItemIds.filter((lid) => lid !== libraryItem.id) // Filter it out
208	      }
209	    }
210	
211	    // Stop and remove cron if no more library items
212	    if (!podcastCron.libraryItemIds.length) {
213	      this.removePodcastEpisodeCron(podcastCron)
214	      return
215	    }
216	
217	    Logger.debug(`[CronManager] Finished executing podcast cron ${expression} for ${libraryItems.length} item(s)`)
218	    this.podcastCronExpressionsExecuting = this.podcastCronExpressionsExecuting.filter((exp) => exp !== expression)
219	  }
220	
221	  removePodcastEpisodeCron(podcastCron) {
222	    Logger.info(`[CronManager] Stopping & removing podcast episode cron for ${podcastCron.expression}`)
223	    if (podcastCron.task) podcastCron.task.stop()
224	    this.podcastCrons = this.podcastCrons.filter((pc) => pc.expression !== podcastCron.expression)
225	  }
226	
227	  /**
228	   *
229	   * @param {import('../models/LibraryItem')} libraryItem
230	   */
231	  checkUpdatePodcastCron(libraryItem) {
232	    // Remove from old cron by library item id
233	    const existingCron = this.podcastCrons.find((pc) => pc.libraryItemIds.includes(libraryItem.id))
234	    if (existingCron) {
235	      existingCron.libraryItemIds = existingCron.libraryItemIds.filter((lid) => lid !== libraryItem.id)
236	      if (!existingCron.libraryItemIds.length) {
237	        this.removePodcastEpisodeCron(existingCron)
238	      }
239	    }
240	
241	    // Add to cron or start new cron
242	    if (libraryItem.media.autoDownloadEpisodes && libraryItem.media.autoDownloadSchedule) {
243	      const cronMatchingExpression = this.podcastCrons.find((pc) => pc.expression === libraryItem.media.autoDownloadSchedule)
244	      if (cronMatchingExpression) {
245	        cronMatchingExpression.libraryItemIds.push(libraryItem.id)
246	
247	        // TODO: Update after old model removed
248	        const podcastTitle = libraryItem.media.title || libraryItem.media.metadata?.title
249	        Logger.info(`[CronManager] Added podcast "${podcastTitle}" to auto dl episode cron "${cronMatchingExpression.expression}"`)
250	      } else {
251	        this.startPodcastCron(libraryItem.media.autoDownloadSchedule, [libraryItem.id])
252	      }
253	    }
254	  }
255	}
256	module.exports = CronManager
