// Scratch helper (set1): transpile single files with the project's compiler options and write them into the scratch folder.
const ts = require(process.argv[2] + '/node_modules/typescript')
const fs = require('fs')
const path = require('path')
const repo = process.argv[2]
const out = process.argv[3]
for (const rel of process.argv.slice(4)) {
  const src = fs.readFileSync(path.join(repo, rel), 'utf8')
  const res = ts.transpileModule(src, { fileName: rel, compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.CommonJS, esModuleInterop: true, strict: true, resolveJsonModule: true } })
  const dest = path.join(out, path.basename(rel).replace(/\.ts$/, '.js'))
  fs.writeFileSync(dest, res.outputText)
  console.log('wrote', dest, res.outputText.length)
}
